custom['free_single']=phase(r'\draw[guide](1,1)--(3.5,1);\fill(1,1)circle(3pt)node[above=5pt]{$(q_0,p_0)$};\fill(3.5,1)circle(3pt)node[above=5pt]{$(q(t),p_0)$};\draw[force](1.3,1)--(3.2,1);\node at(2,-1){$G=q-pt/m=q_0$};')
custom['simple_levels']=picture(r'\draw[->](0,-.4)--(0,5)node[above]{$E$};\draw[guide](.3,4.4)--(3.4,4.4)node[right]{$0$};\draw[ink,thick](.3,0)--(3.4,0)node[right]{$E_1=-E_R$};\draw[ink,thick](.3,3.3)--(3.4,3.3)node[right]{$E_2=-E_R/4$};\draw[ink,thick](.3,3.911)--(3.4,3.911)node[right]{$E_3=-E_R/9$};\draw[force](1.3,3.3)--(1.3,0)node[midway,right]{$h\nu=E_2-E_1$};\node at(2,-1){$E_n=-E_R/n^2$};')
custom['wkb']=picture(r'\draw[->](-.2,0)--(5.3,0)node[right]{$x$};\draw[guide,domain=0:5,samples=80]plot(\x,{exp(-.16*(\x-2.5)^2)});\draw[guide,domain=0:5,samples=80]plot(\x,{-exp(-.16*(\x-2.5)^2)});\draw[ink,domain=0:5,samples=180]plot(\x,{exp(-.16*(\x-2.5)^2)*cos(600*\x)});\draw[<->](2,1.35)--(2.6,1.35)node[midway,above]{$\lambda$};\draw[<->](.4,-1.4)--(4.6,-1.4)node[midway,below]{$l_A$};')
used=[]
for kind,data in [('ex',rows),('tr',training)]:
 for n,r in data.items():
  key=f'{kind}{n:02}';fig=r['fig']
  src=(P/f'补充图/c5-diagram-{fig:02}.tex').read_text() if isinstance(fig,int) else custom[fig]
  if kind=='tr' and n==11:src=src.replace(r'b(q)\text{ 或 }f_q',r'f_q').replace('p-b(q)','p-f_q')
  if kind=='tr' and n==6:src=src.replace(r'b(q)\text{ 或 }f_q',r'b(q)')
  if n==51 and kind=='ex':src=src.replace('$m_1$','$m$').replace('$m_2$','$m$')
  if n==23 and kind=='ex':src=src.replace('$P_1$','$m_1g$').replace('$P_2$','$m_2g$')
  src=re.sub(r'circle\((\d+(?:\.\d+)?)pt\)node\[(above right|above left|below right|below left|right|left|above|below)\]',lambda m:'circle('+m[1]+'pt)node['+m[2]+'='+str(float(m[1])+2)+'pt]' if float(m[1])>=3 else m[0],src)
  (P/f'题图/{key}.tex').write_text('% '+r['bridge']+'\n'+src)
  # A genuine model panel plus the equation-to-result process, kept as editable TikZ.
  # Each formula is independently fitted, so long matrix/field equations do not overlap.
  sol=r'''\begin{tikzpicture}
\node[inner sep=0,anchor=center] at(-3.5,0){\adjustbox{max width=6.2cm,max height=4.8cm}{\input{题图/KEY.tex}}};
\node[anchor=center,align=center,inner sep=0] (eq1) at(3.7,1){\adjustbox{max width=6.4cm}{$\displaystyle EQ1$}};
\draw[force](3.7,.45)--(3.7,-.45);
\node[anchor=center,align=center,inner sep=0] (eq2) at(3.7,-1){\adjustbox{max width=6.4cm}{$\displaystyle EQ2$}};
\end{tikzpicture}
'''.replace('KEY',key).replace('EQ1',r['a']).replace('EQ2',r['b'])
  if r['fig'] in (3,4,13,30,40,42,45,46,47,48,52,59,'four_models','cyclic_three','atwood_pair','tangent_pair','cart_modes','two_osc','quantum_spread','elastic_waves'):
   sol=r'''\begin{tikzpicture}
\node[inner sep=0,anchor=center]at(0,1.2){\adjustbox{max width=13cm,max height=4.4cm}{\input{题图/KEY.tex}}};
\node[inner sep=0,anchor=center]at(-3.7,-2.2){\adjustbox{max width=5.8cm}{$\displaystyle EQ1$}};
\draw[force](-.5,-2.2)--(.5,-2.2);
\node[inner sep=0,anchor=center]at(3.7,-2.2){\adjustbox{max width=5.8cm}{$\displaystyle EQ2$}};
\end{tikzpicture}'''.replace('KEY',key).replace('EQ1',r['a']).replace('EQ2',r['b'])
  (P/f'解答图/{key}.tex').write_text(sol);used.append({'key':key,**r})
(P/'资料核查/逐题图解清单.json').write_text(json.dumps(used,ensure_ascii=False,indent=2))
print('Wrote',len(used),'question and solution model/process drawings')
